def solve(base, name):
    if name.startswith("/"):
        return "error"

    def norm(path):
        parts = []
        for part in path.split("/"):
            if part in ("", "."):
                continue
            if part == "..":
                if not parts:
                    return "error"
                parts.pop()
            else:
                parts.append(part)
        return "/" + "/".join(parts)

    base_n = norm(base)
    if base_n == "error":
        return "error"
    joined = base.rstrip("/") + "/" + name
    full = norm(joined)
    if full == "error":
        return "error"
    if full == base_n or full.startswith(base_n + "/"):
        return full
    return "error"
